  对手等级: number; // 新增：敌人等级
  对手魅力: number;
  对手幸运: number;
  对手闪避率: number;
  对手暴击率: number;
  // 已移除：对手意志力
  对手耐力: number;
  对手最大耐力: number;
  对手快感: number;
  对手最大快感: number;
  对手高潮次数: number;
