                }
                // 物品逻辑结束
                // 解析临时状态列表为 StatusEffect[]
                const statusList = _.get(data, '临时状态.状态列表', {});
                console.info('[战斗界面] Raw Status List:', statusList);
                const effects = [];
                Object.entries(statusList).forEach(([name, val]) => {
                    // 获取持续时间和加成信息
                    let duration = 0;
                    let bonuses = {};
                    if (typeof val === 'number') {
                        duration = val;
                    }
                    else if (typeof val === 'object' && val !== null) {
                        duration = _.get(val, '剩余回合', 0);
                        bonuses = _.get(val, '加成', {});
                    }
                    if (duration <= 0)
                        return;
                    // 从加成信息生成显示名称
                    let displayName = '';
                    let type = 'buff';
                    let icon = '⚡';
                    // 如果有加成信息，格式化显示
                    if (Object.keys(bonuses).length > 0) {
                        const bonusTexts = [];
                        for (const [key, value] of Object.entries(bonuses)) {
                            if (value === 0)
                                continue;
                            // 映射加成键名到显示名称
                            const attrMap = {
                                魅力加成: '魅力',
                                幸运加成: '幸运',
                                闪避率加成: '闪避',
                                暴击率加成: '暴击',
                                基础性斗力加成: '性斗力',
                                基础性斗力成算: '性斗力%',
                                基础忍耐力加成: '忍耐力',
                                基础忍耐力成算: '忍耐力%',
                            };
                            const attrName = attrMap[key] || key;
                            const sign = value > 0 ? '+' : '';
                            bonusTexts.push(`${attrName}${sign}${value}`);
                            // 判断是buff还是debuff
                            if (value < 0) {
                                type = 'debuff';
                            }
                        }
                        displayName = bonusTexts.join(', ');
                    }
                    else {
                        // 没有加成信息，使用原名称
                        displayName = name;
                    }
                    // 根据类型设置图标
                    if (type === 'debuff') {
                        icon = '▼';
                    }
                    else {
                        icon = '▲';
                    }
                    // 特殊状态图标映射
                    if (name.includes('敏感'))
                        icon = '❤️';
                    if (name.includes('沉默'))
                        icon = '😶';
                    if (name.includes('束缚'))
                        icon = '⛓️';
                    if (name.includes('无敌'))
                        icon = '🛡️';
                    if (name.includes('必暴'))
                        icon = '💥';
                    effects.push({
                        id: name,
                        name: displayName || name,
                        duration: duration,
                        icon: icon,
                        type: type,
                        effect: {
                            type: 'focus',
                            value: 0,
                            isPercent: false,
                            duration: duration,
                            stackable: false,
                        },
                    });
                });
                player.value.statusEffects = effects;
                // 应用临时状态和永久状态的加成
                const tempBonus = _.get(data, '临时状态.加成统计', {});
                const permBonus = _.get(data, '永久状态.加成统计', {});
                const equipBonus = _.get(data, '物品系统.装备总加成', {});
                // 计算总加成（这里只是示例，实际应该根据加成类型进行计算）
                // 注意：这些加成应该在战斗计算时应用，而不是直接修改基础值
                // 读取允许认输设置（注意：true时不可认输，false时允许认输）
                const surrenderAllowed = _.get(data, '性斗系统.胜负规则.允许认输', true);
                allowSurrender.value = !surrenderAllowed; // 反转逻辑：true时不可认输，false时允许认输
                // 同步回合数
                turnState.currentTurn = _.get(data, '性斗系统.当前回合', 1);
                console.info('[战斗界面] 已从MVU加载数据');
            }
            catch (e) {
                console.warn('[战斗界面] MVU加载失败，使用默认数据', e);
            }
        }
        // 从MVU数据加载敌人（后备方案）
