                    let bonuses = {};
                    if (typeof val === 'number') {
                        duration = val;
                    }
                    else if (typeof val === 'object' && val !== null) {
                        duration = _.get(val, '剩余回合', 0);
                        bonuses = _.get(val, '加成', {});
                    }
                    if (duration <= 0)
                        return;
                    let displayName = '';
                    let type = 'buff';
                    let icon = '⚡';
                    if (Object.keys(bonuses).length > 0) {
                        const bonusTexts = [];
                        for (const [key, value] of Object.entries(bonuses)) {
                            if (value === 0)
                                continue;
                            const attrMap = {
                                魅力加成: '魅力',
                                幸运加成: '幸运',
                                闪避率加成: '闪避',
                                暴击率加成: '暴击',
                                基础性斗力加成: '性斗力',
                                基础性斗力成算: '性斗力%',
                                基础忍耐力加成: '忍耐力',
                                基础忍耐力成算: '忍耐力%',
                            };
                            const attrName = attrMap[key] || key;
                            const sign = value > 0 ? '+' : '';
                            bonusTexts.push(`${attrName}${sign}${value}`);
                            if (value < 0)
                                type = 'debuff';
                        }
                        displayName = bonusTexts.join(', ');
                    }
                    else {
                        displayName = name;
                    }
                    if (type === 'debuff')
                        icon = '▼';
                    else
                        icon = '▲';
                    if (name.includes('敏感'))
                        icon = '❤️';
                    if (name.includes('沉默'))
                        icon = '😶';
                    if (name.includes('束缚'))
                        icon = '⛓️';
                    if (name.includes('无敌'))
                        icon = '🛡️';
                    if (name.includes('必暴'))
                        icon = '💥';
                    playerEffects.push({
                        id: name,
                        name: displayName || name,
                        duration: duration,
                        icon: icon,
                        type: type,
                        effect: { type: 'focus', value: 0, isPercent: false, duration: duration, stackable: false },
                    });
                });
                player.value.statusEffects = playerEffects;
                // 获取天赋加成
                const playerTalentBonus = {};
                if (playerTalent.value?.bonus) {
                    const tb = playerTalent.value.bonus;
                    if (tb.基础性斗力加成)
                        playerTalentBonus['基础性斗力加成'] = tb.基础性斗力加成;
                    if (tb.基础性斗力成算)
                        playerTalentBonus['基础性斗力成算'] = tb.基础性斗力成算;
                    if (tb.基础忍耐力加成)
                        playerTalentBonus['基础忍耐力加成'] = tb.基础忍耐力加成;
                    if (tb.基础忍耐力成算)
                        playerTalentBonus['基础忍耐力成算'] = tb.基础忍耐力成算;
                    if (tb.魅力加成)
                        playerTalentBonus['魅力加成'] = tb.魅力加成;
                    if (tb.幸运加成)
                        playerTalentBonus['幸运加成'] = tb.幸运加成;
                    if (tb.闪避率加成)
                        playerTalentBonus['闪避率加成'] = tb.闪避率加成;
                    if (tb.暴击率加成)
                        playerTalentBonus['暴击率加成'] = tb.暴击率加成;
                }
                // 写入玩家的临时状态加成统计
                _.set(data, '临时状态.加成统计', playerTempBonus);
                // 玩家性斗力（加入天赋加成）
                const playerBaseSexPower = _.get(data, '核心状态.$基础性斗力', 10);
                const playerSexPowerBonus = (playerTempBonus.基础性斗力加成 || 0) +
                    (playerPermBonus.基础性斗力加成 || 0) +
                    (playerEquipBonus.基础性斗力加成 || 0) +
                    (playerTalentBonus['基础性斗力加成'] || 0);
                const playerSexPowerMultiplier = ((playerTempBonus.基础性斗力成算 || 0) +
                    (playerPermBonus.基础性斗力成算 || 0) +
                    (playerEquipBonus.基础性斗力成算 || 0) +
                    (playerTalentBonus['基础性斗力成算'] || 0)) /
                    100;
                const calculatedSexPower = Math.max(0, Math.round((playerBaseSexPower + playerSexPowerBonus) * (1 + playerSexPowerMultiplier)));
                player.value.stats.sexPower = calculatedSexPower;
                // 玩家忍耐力（加入天赋加成）
                const playerBaseEndurance = _.get(data, '核心状态.$基础忍耐力', 10);
                const playerEnduranceBonus = (playerTempBonus.基础忍耐力加成 || 0) +
                    (playerPermBonus.基础忍耐力加成 || 0) +
                    (playerEquipBonus.基础忍耐力加成 || 0) +
                    (playerTalentBonus['基础忍耐力加成'] || 0);
                const playerEnduranceMultiplier = ((playerTempBonus.基础忍耐力成算 || 0) +
                    (playerPermBonus.基础忍耐力成算 || 0) +
                    (playerEquipBonus.基础忍耐力成算 || 0) +
                    (playerTalentBonus['基础忍耐力成算'] || 0)) /
                    100;
                const calculatedEndurance = Math.max(0, Math.round((playerBaseEndurance + playerEnduranceBonus) * (1 + playerEnduranceMultiplier)));
                player.value.stats.baseEndurance = calculatedEndurance;
                // 写入玩家实时值
                _.set(data, '性斗系统.实时性斗力', calculatedSexPower);
                _.set(data, '性斗系统.实时忍耐力', calculatedEndurance);
                // 玩家其他属性（加入天赋加成，确保不小于0）
                player.value.stats.charm = Math.max(0, _.get(data, '核心状态.$基础魅力', 10) +
                    (playerTempBonus.魅力加成 || 0) +
                    (playerPermBonus.魅力加成 || 0) +
                    (playerEquipBonus.魅力加成 || 0) +
                    (playerTalentBonus['魅力加成'] || 0));
                player.value.stats.luck = Math.max(0, _.get(data, '核心状态.$基础幸运', 10) +
                    (playerTempBonus.幸运加成 || 0) +
                    (playerPermBonus.幸运加成 || 0) +
                    (playerEquipBonus.幸运加成 || 0) +
                    (playerTalentBonus['幸运加成'] || 0));
                player.value.stats.evasion = calcEvasionWithDiminishingReturns(_.get(data, '核心状态.$基础闪避率', 0) +
                    (playerTempBonus.闪避率加成 || 0) +
                    (playerPermBonus.闪避率加成 || 0) +
                    (playerEquipBonus.闪避率加成 || 0) +
                    (playerTalentBonus['闪避率加成'] || 0));
                player.value.stats.crit = Math.min(100, Math.max(0, _.get(data, '核心状态.$基础暴击率', 0) +
                    (playerTempBonus.暴击率加成 || 0) +
                    (playerPermBonus.暴击率加成 || 0) +
                    (playerEquipBonus.暴击率加成 || 0) +
                    (playerTalentBonus['暴击率加成'] || 0)));
                // 快感和高潮次数
                player.value.stats.currentPleasure = _.get(data, '核心状态.$快感', 0);
                player.value.stats.maxPleasure = _.get(data, '核心状态.$最大快感', 100);
                player.value.stats.climaxCount = _.get(data, '性斗系统.高潮次数', 0);
                enemy.value.stats.currentPleasure = _.get(data, '性斗系统.对手快感', 0);
                enemy.value.stats.maxPleasure = _.get(data, '性斗系统.对手最大快感', 100);
                enemy.value.stats.climaxCount = _.get(data, '性斗系统.对手高潮次数', 0);
                await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
                // === 对手属性计算（调用专用函数）===
                await updateEnemyRealtimeStats();
            }
            catch (e) {
                console.error('[战斗界面] 重新读取状态失败', e);
            }
        }
        // 触发战斗特效
