        function addLog(message, source, type = 'info') {
            const logEntry = {
                id: Math.random().toString(36).substr(2, 9),
                turn: turnState.currentTurn,
                message,
                source,
                type,
            };
            logs.value.push(logEntry);
            // 同时异步写入MVU的行动日志（不阻塞UI）
            (async () => {
                try {
                    if (typeof Mvu !== 'undefined') {
                        const mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
                        if (mvuData) {
                            const logKey = `回合${turnState.currentTurn}_${Date.now()}`;
                            const logValue = `[${logEntry.turn}] ${logEntry.source === 'player' ? player.value.name : logEntry.source === 'enemy' ? enemy.value.name : '系统'}: ${logEntry.message}`;
                            const currentLogs = _.get(mvuData.stat_data, '性斗系统.行动日志', {});
                            const updatedLogs = { ...currentLogs, [logKey]: logValue };
                            _.set(mvuData.stat_data, '性斗系统.行动日志', updatedLogs);
                            // 异步保存，不阻塞UI
                            await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
                        }
                    }
                }
                catch (e) {
                    console.warn('[战斗界面] 写入行动日志失败', e);
                }
            })();
        }
        function cloneCharacter(char) {
            return {
                ...char,
                stats: { ...char.stats },
                skills: char.skills.map(s => ({ ...s })),
                items: char.items.map(i => ({ ...i })),
                statusEffects: [...char.statusEffects],
            };
        }
        function getPhaseText(phase) {
            const texts = {
                playerInput: '玩家回合',
                processing: '结算中',
                enemyAction: '敌方行动',
                victory: '胜利',
                defeat: '败北',
                climaxResolution: '高潮处理',
                gameOver: '游戏结束',
