                        // 薇丝佩菈BOSS战：敌人使用技能后触发随机战斗对话
                        if (BossSystem.bossState.isBossFight && BossSystem.bossState.bossId === 'vespera') {
                            let playerGender = '男';
                            try {
                                if (typeof Mvu !== 'undefined') {
