                            catch (e) {
                                playerGender = '男';
                            }
                            playerGender = playerGender === '男' ? '男' : '女';
                            const battleDialogue = BossSystem.getVesperaRandomBattleDialogue(playerGender);
                            if (battleDialogue) {
                                BossSystem.queueDialogues([battleDialogue]);
