                                            stateList['卡路里加成'] = {
                                                加成: {
                                                    基础性斗力成算: calorieBonus.sexPowerCalcBonus,
                                                    基础忍耐力成算: calorieBonus.enduranceCalcBonus,
                                                    魅力加成: calorieBonus.charmCalcBonus,
